#!/usr/bin/env python3
"""WISE2 Commander cinematic read-only monitoring; tailnet-only binding."""
import json,os,shutil,subprocess,time
from urllib.parse import urlsplit
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
PORT=18781
SERVICES=['wise2-jarvis','wise2-video-worker','wise2-trading','wise2-godseye-real','wise2-shannon-staging','desktop-commander']
def state(s):
 try:
  r=subprocess.run(['systemctl','--user','is-active',s+'.service'],capture_output=True,text=True,timeout=2)
  return r.stdout.strip() or 'unknown'
 except Exception:return 'unknown'
def status():
 d=shutil.disk_usage('/');m={}
 with open('/proc/meminfo') as f:
  for l in f:
   k,v=l.split(':',1);m[k]=int(v.split()[0])*1024
 used=m['MemTotal']-m['MemAvailable']
 with open('/proc/uptime') as f: uptime=int(float(f.read().split()[0]))
 return dict(host=os.uname().nodename,uptime=uptime,load=round(os.getloadavg()[0],2),disk_percent=round(d.used/d.total*100,1),disk_free_gb=round(d.free/1e9,1),memory_percent=round(used/m['MemTotal']*100,1),services={s:state(s) for s in SERVICES},mode='read-only',timestamp=int(time.time()))
HTML=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#020917"><title>WISE² Commander · IMP</title><style>
:root{color-scheme:dark;--blue:#67d8ff;--line:#1b5674;--bg:#020917}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 75% 0%,#0c3a57 0%,transparent 50%),var(--bg);color:#e8f7ff;font:15px system-ui,-apple-system,sans-serif}main{max-width:1200px;margin:auto;padding:26px 20px 80px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #24506c;padding-bottom:18px;gap:10px}.brand{font-size:22px;font-weight:900;letter-spacing:.24em}.tag{font-size:11px;letter-spacing:.2em;color:var(--blue)}.pill{border:1px solid #276487;border-radius:30px;padding:9px 12px;font-size:11px;color:#9ceaff}.hero{display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:center;padding:50px 0 20px}.eyebrow{color:var(--blue);letter-spacing:.3em;font-size:11px;font-weight:700}h1{font-size:clamp(42px,7vw,90px);line-height:.94;letter-spacing:.08em;margin:20px 0;text-shadow:0 0 30px #137ba080}p{color:#a7c4d7;line-height:1.6}.orb{position:relative;aspect-ratio:1;max-width:390px;margin:auto;width:100%;border-radius:50%;background:radial-gradient(circle at 43% 40%,#1c7aaf44,transparent 45%),radial-gradient(circle,#07345655 10%,#030d1c 68%);border:1px solid #2073a055;box-shadow:0 0 80px #0b8de52a,inset 0 0 60px #0b8de52a;display:grid;place-items:center;overflow:hidden}.orb:before,.orb:after{content:"";position:absolute;inset:12%;border:1px solid #4ad4ff66;border-radius:50%;transform:rotateX(66deg) rotate(25deg);box-shadow:0 0 24px #0c9de644}.orb:after{transform:rotateY(67deg) rotate(-20deg)}.orb span{font-weight:900;font-size:clamp(70px,12vw,125px);letter-spacing:.03em;text-shadow:0 0 30px #24c7ff;z-index:1}.section{margin-top:35px}.section h2{font-size:12px;letter-spacing:.28em;color:var(--blue)}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:linear-gradient(145deg,#0a2b41d9,#041322e8);border:1px solid #246182;border-radius:12px;padding:22px;min-width:0}.metric{font-size:clamp(25px,4vw,40px);font-weight:850;letter-spacing:-.04em;margin:14px 0 3px}.sub{font-size:12px;color:#91b2c6}.services{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.service{display:flex;align-items:center;justify-content:space-between;gap:10px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:#a7a7a7;margin-right:8px}.dot.ok{background:#40efb1;box-shadow:0 0 12px #40efb1}.dot.bad{background:#ff927b}.name{overflow-wrap:anywhere;font-size:13px}.status{font-size:11px;color:#b5d4e5}.modules{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.module{min-height:100px}.module b{display:block;margin-top:14px;font-size:15px}.locked{font-size:11px;color:#f5c88c;margin-top:12px}button{cursor:pointer;background:#0c4766;color:#e5f8ff;border:1px solid #4bb2e1;border-radius:8px;padding:12px 16px;font-weight:700}button:focus-visible{outline:3px solid white}footer{margin-top:30px;color:#88a9bf;font-size:12px}.warning{color:#ffcc91}@media(max-width:760px){.hero{grid-template-columns:1fr;padding:30px 0}.orb{max-width:260px}.grid,.modules{grid-template-columns:repeat(2,1fr)}.services{grid-template-columns:1fr}main{padding:20px 16px 70px}.card{padding:16px}}@media(prefers-reduced-motion:no-preference){.orb{animation:glow 5s ease-in-out infinite alternate}@keyframes glow{to{box-shadow:0 0 100px #158de85a,inset 0 0 70px #0b8de55a}}}
</style></head><body><main><header><div><div class="brand">WISE²</div><div class="tag">CREATIVE SYSTEMS / NODE 01</div></div><div class="pill" id="connection" role="status">CONNECTING</div></header><div class="hero"><div><div class="eyebrow">IMP / INTELLIGENT MISSION PLATFORM</div><h1>COMMAND<br>CENTER</h1><p>Cinematic mission control with real Node 01 telemetry. Private tailnet access. Read-only operations until authenticated controls are approved.</p><button id="refresh">REFRESH TELEMETRY</button><p id="updated" aria-live="polite"></p></div><div class="orb" aria-label="WISE2 IMP holographic emblem"><span>IMP</span></div></div><section class="section"><h2>01 / LIVE NODE TELEMETRY</h2><div class="grid"><div class="card"><div class="tag">STORAGE USED</div><div class="metric" id="disk">...</div><div class="sub" id="free">Loading</div></div><div class="card"><div class="tag">MEMORY USED</div><div class="metric" id="mem">...</div><div class="sub">System memory</div></div><div class="card"><div class="tag">CPU LOAD / 1M</div><div class="metric" id="load">...</div><div class="sub">Linux load average</div></div><div class="card"><div class="tag">UPTIME</div><div class="metric" id="uptime">...</div><div class="sub" id="host">Node 01</div></div></div></section><section class="section"><h2>02 / SERVICE MATRIX</h2><div id="services" class="services"></div></section><section class="section"><h2>03 / MISSION MODULES</h2><div class="modules"><div class="card module"><div class="tag">01 / AUDIO</div><b>SOUND LABS</b><div class="locked">INTEGRATION PENDING</div></div><div class="card module"><div class="tag">02 / INTELLIGENCE</div><b>AI ORCHESTRATOR</b><div class="locked">INTEGRATION PENDING</div></div><div class="card module"><div class="tag">03 / PRODUCTION</div><b>LIVE STUDIO</b><div class="locked">INTEGRATION PENDING</div></div><div class="card module"><div class="tag">04 / SYSTEMS</div><b>THE HIVE</b><div class="locked">INTEGRATION PENDING</div></div></div></section><footer>WISE² COMMANDER V2 · READ ONLY · DEPLOYMENTS, LOGS & REMOTE EXECUTION LOCKED UNTIL AUTHENTICATED AUDITABLE BACKEND IS READY.</footer></main><script>
const el=id=>document.getElementById(id);let pending=false;
async function refresh(){if(pending)return;pending=true;try{const response=await fetch('/api/status',{cache:'no-store'});if(!response.ok)throw Error('HTTP '+response.status);const d=await response.json();el('disk').textContent=d.disk_percent+'%';el('free').textContent=d.disk_free_gb+' GB free';el('mem').textContent=d.memory_percent+'%';el('load').textContent=d.load.toFixed(2);el('uptime').textContent=Math.floor(d.uptime/86400)+'d '+Math.floor(d.uptime%86400/3600)+'h';el('host').textContent=d.host;const container=el('services');container.replaceChildren(...Object.entries(d.services).map(([name,value])=>{const box=document.createElement('div');box.className='card service';const left=document.createElement('div');const dot=document.createElement('span');dot.className='dot '+(value==='active'?'ok':'bad');const label=document.createElement('span');label.className='name';label.textContent=name;left.append(dot,label);const right=document.createElement('span');right.className='status';right.textContent=value;box.append(left,right);return box}));el('connection').textContent='LIVE · READ ONLY';el('updated').textContent='Updated '+new Date().toLocaleTimeString();el('updated').className='';}catch(e){el('connection').textContent='CONNECTION LOST';el('updated').textContent='Telemetry unavailable: '+e.message;el('updated').className='warning'}finally{pending=false}}
el('refresh').addEventListener('click',refresh);refresh();setInterval(refresh,15000);
</script></body></html>'''
class Handler(BaseHTTPRequestHandler):
 def do_GET(self):
  path=urlsplit(self.path).path
  if path in ('/','/index.html'): body=HTML.encode();kind='text/html';code=200
  elif path=='/api/health':body=b'{"status":"ok","mode":"read-only","version":2}';kind='application/json';code=200
  elif path=='/api/status':body=json.dumps(status()).encode();kind='application/json';code=200
  else:body=b'Not found';kind='text/plain';code=404
  self.send_response(code)
  for k,v in [('Content-Type',kind+'; charset=utf-8'),('Content-Length',str(len(body))),('Cache-Control','no-store'),('X-Content-Type-Options','nosniff'),('X-Frame-Options','DENY'),('Referrer-Policy','no-referrer'),('Content-Security-Policy',"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'")]:self.send_header(k,v)
  self.end_headers();self.wfile.write(body)
 def do_POST(self):self.send_error(405,'Read-only')
if __name__=='__main__':ThreadingHTTPServer(('127.0.0.1',PORT),Handler).serve_forever()
